import numpy as np
x=np.array([1.,2.,3.,4.5,6.]); y=np.array([18.,25.,34.,44.,55.])
def loss(w): return np.mean((w*x-y)**2)
def grad(w): return np.mean(2*(w*x-y)*x)
def descend(lr,tol=1e-6,max_steps=10000):
 w,prev=0.,loss(0.)
 for step in range(1,max_steps+1):
  w-=lr*grad(w); cur=loss(w)
  if abs(prev-cur)<tol: return w,step
  prev=cur
 return w,max_steps
